  "inlineSchema": "// Fieldward — data model for the shared trip-planning board.\n//\n// The pivot in one line: there is no shop here. A human and their AI agent\n// jointly assemble a trip on one spatial board; the end state is a locked\n// plan, never an order.\n//\n// Money is still stored in cents (Int) to avoid floating-point drift. Board\n// positions are floats in board-relative pixels (see src/lib/board-geometry.ts\n// for bounds and the default-placement scan). SQLite has no native array\n// type, so GearItem.tags and Proposal.payloadJson are JSON-encoded strings,\n// parsed in the app layer (src/lib/gear.ts, src/lib/proposals.ts).\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// The gear library (was Product). `availability` is flavor text, not a count:\n// in a planning tool the useful signal is \"can I actually get this before the\n// trip?\" — \"Low stock — 3 left\", \"Waitlist until March\" — not a warehouse\n// integer. Price is the reference cost used for budget math on the board.\nmodel GearItem {\n  id           String      @id @default(cuid())\n  name         String\n  description  String\n  price        Int // cents\n  category     String\n  tags         String // JSON string array, parsed in app layer\n  imageUrl     String\n  availability String      @default(\"In stock\")\n  boardItems   BoardItem[]\n}\n\n// One movable object on the board (was CartItem). Two itemTypes share this\n// table — simplest option, since both types get identical drag/poll/note\n// plumbing and one tool surface:\n//\n//   \"gear\" — a GearItem pinned to the board (gearItemId set, quantity ≥ 1)\n//   \"day\"  — a route/day segment card the human authors (label + text)\n//\n// Budget is deliberately NOT a BoardItem: it lives on TripBrief (the shared\n// framing object) and the board renders it as a derived roll-up, so there is\n// exactly one source of truth for the budget.\nmodel BoardItem {\n  id         String    @id @default(cuid())\n  sessionId  String\n  itemType   String // \"gear\" | \"day\"\n  gearItemId String?\n  label      String? // day blocks: \"Day 1 — Cairn Lake\"\n  text       String? // day blocks: segment notes (\"6 mi, 1,900 ft gain\")\n  quantity   Int       @default(1) // gear only\n  addedBy    String // \"human\" | \"agent\"\n  // Optional first-person reasoning left by the agent tool call — rendered\n  // beside the card as the agent's \"voice\". Nullable: most cards (and every\n  // human-placed card) carry none.\n  note       String?\n  x          Float\n  y          Float\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n  gearItem   GearItem? @relation(fields: [gearItemId], references: [id])\n\n  @@index([sessionId])\n}\n\n// One per browser session: what the trip is and what it should cost — the\n// shared ground both the human and the agent work from (was ShoppingContext).\n//\n// location/startDate/endDate are the HUMAN's factual inputs (where the trip\n// happens, when it runs) — they ground the weather outlook and, through it,\n// the readiness check. Stored as noon-UTC DateTimes so timezone math can\n// never flip the calendar day; the API speaks plain YYYY-MM-DD strings.\n//\n// lockedAt is the trust boundary: set ONLY by the human \"Lock this plan\"\n// button (POST /api/brief/lock). No WebMCP tool touches it. While set, every\n// board mutation is refused server-side.\n//\n// Pending agent suggestions live in the Proposal table now (one row per\n// kind — brief updates, day orders): the same accept/dismiss mechanism for\n// every consequential thing the agent wants to influence.\nmodel TripBrief {\n  id              String    @id @default(cuid())\n  sessionId       String    @unique\n  tripDescription String    @default(\"\")\n  budget          Int? // cents\n  location        String? // free-text place name, e.g. \"Rocky Mountain National Park\"\n  startDate       DateTime? // noon UTC of the first trip day\n  endDate         DateTime? // noon UTC of the last trip day\n  lockedAt        DateTime?\n  updatedBy       String    @default(\"human\") // who wrote the CURRENT values\n  updatedAt       DateTime  @updatedAt\n}\n\n// One PENDING agent suggestion at a time, per session, per kind:\n//\n//   \"brief\"     — payload {\"tripDescription\"?: string, \"budget\": cents|null}\n//   \"day-order\" — payload {\"orderedBoardItemIds\": string[], \"note\"?: string}\n//\n// The generalized accept/dismiss mechanism (previously TripBrief.proposalJson):\n// agents propose, the human resolves via the matching /resolve route, and\n// nothing consequential changes until they do. Resolved rows are deleted —\n// the activity log is the durable record of verdicts.\nmodel Proposal {\n  id          String   @id @default(cuid())\n  sessionId   String\n  kind        String // \"brief\" | \"day-order\"\n  payloadJson String // kind-specific JSON, parsed in src/lib/proposals.ts\n  createdAt   DateTime @default(now())\n\n  @@unique([sessionId, kind])\n  @@index([sessionId])\n}\n\n// One row per notable action by either party — the shared record both the\n// on-screen toast strip and the get_activity_log WebMCP tool read. This is\n// how the agent \"sees\" what the human has been doing (and vice versa).\nmodel ActivityEvent {\n  id        String   @id @default(cuid())\n  sessionId String\n  actor     String // \"human\" | \"agent\"\n  action    String // e.g. \"view_gear\", \"place_gear\", \"tool:place_on_board\"\n  detail    String // short human-readable line, e.g. \"Agent placed Trail Runner Boots\"\n  createdAt DateTime @default(now())\n\n  @@index([sessionId, createdAt])\n}\n",
